<script lang="ts">
 import type {Component} from 'svelte'; import {tick} from 'svelte'; import {items, storageHref} from '../../lib/stores'; import {loadLazy} from '../../lib/lazy-load';
 type Handle={startExport:()=>void;promptImport:(file:File)=>void}; type Lazy=Component<Record<string,unknown>,Handle>;
 let Modal=$state<Lazy|null>(null);let modal=$state<Handle|null>(null);let open=$state(false);let picker=$state<HTMLInputElement|null>(null); const all=$derived(Object.values($items)); const counts=$derived({bookmarks:all.filter(i=>i.type==='bookmark').length,notes:all.filter(i=>i.type==='note').length,files:all.filter(i=>i.type==='document'||i.type==='image').length,voice:all.filter(i=>i.type==='audio').length});
 async function load(){Modal??=await loadLazy<Lazy>(()=>import('../ImportExportModal.svelte'));await tick()} async function exportData(){await load();modal?.startExport()} function choose(){picker?.click()} async function selected(e:Event){const input=e.target as HTMLInputElement;const file=input.files?.[0];if(file){await load();modal?.promptImport(file)}input.value=''}
</script>
<div class="settings-section">{#if $storageHref}<div class="row"><div class="row-main"><div class="row-label">Storage server</div><div class="row-desc">Backed by <a href="https://remotestorage.io" target="_blank" rel="noreferrer">remoteStorage</a>, an open standard for user-owned storage — your data lives at <a href={$storageHref} target="_blank" rel="noreferrer">{$storageHref}</a>, not on our servers.</div></div></div>{/if}<div class="row"><div class="row-main"><div class="row-label">{all.length} items on your storage server</div><div class="row-desc">{counts.bookmarks} bookmarks · {counts.notes} notes · {counts.files} files · {counts.voice} voice notes</div></div></div><div class="row"><div class="row-main"><div class="row-label">Export a backup</div><div class="row-desc">One .zip with every item and attached file.</div></div><div class="row-ctl"><button class="btn" type="button" onclick={()=>void exportData()}>Export .zip</button></div></div><div class="row"><div class="row-main"><div class="row-label">Restore from a backup</div><div class="row-desc">Merges a .zip back in. Nothing already in your inbox is removed.</div></div><div class="row-ctl"><button class="btn" type="button" onclick={choose}>Choose file…</button><input class="hidden" bind:this={picker} type="file" accept=".zip" onchange={selected}/></div></div></div>
{#if Modal}<Modal bind:this={modal} bind:open/>{/if}<style>.hidden{display:none}</style>
